import { Component } from '@angular/core';
import { ActivatedRoute, Router, RouterOutlet } from '@angular/router';
import { FormularioFlotanteComponent } from "../../../shared/formulario-flotante/formulario-flotante.component";
import { UtilsService } from '../../../services/utils.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';

@Component({
    selector: 'app-credito-form',
    imports: [
        RouterOutlet,
    ],
    templateUrl: './credito-form.component.html',
    styleUrl: './credito-form.component.css'
})
export class CreditoFormComponent {
  credito_id:number=0
  credito?:Credito
  constructor(
    private utils:UtilsService,
    private route: ActivatedRoute,
    public creditoController: CreditoService,
    private router: Router,
  ){}

  async ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const credito_id = this.utils.intOrNull(this.route.snapshot.paramMap.get('credito_id'))
      if(credito_id && this.credito_id!=credito_id){
        this.credito_id=credito_id
        this.credito= await this.creditoController.find(credito_id, ['datosPersonaFisica',"datosPersonasMorales","productosFinancieros"])
        const children= this.route.snapshot.firstChild
        if(children) return
        this.redirect()
      }
    })
  }

  async redirect(){
    if(this.credito?.datos_persona_fisica || this.credito?.productos_financieros?.regimen_fiscal=='PERSONA FISICA CON ACTIVIDAD EMPRESARIAL'){
      this.router.navigate(['pf'], {relativeTo: this.route})
    }
    if(this.credito?.datos_personas_morales || this.credito?.productos_financieros?.regimen_fiscal=='PERSONA MORAL'){
      this.router.navigate(['pm'], {relativeTo: this.route})
    }
  }
}
